  "subject": {
    "description": "young woman seated outside a cozy cafe, face intentionally anonymized with a soft rectangular blur, relaxed and approachable posture, holding an iced drink with both hands",
    "outfit": "{argument name=\"main outfit\" default=\"cream knit cardigan with small pink ribbon details, sailor-neck white top, oversized blush pink bow, pastel pink plaid A-line skirt, scalloped white socks, chunky cream loafers, beige cap, sunglasses resting on cap, pink shoulder bag\"}",
