    "left side": {
      "main photo": "large vertical rounded-corner lifestyle photo occupying about two thirds of the poster height, showing the full seated outfit from head to shoes",
      "thumbnail strip": {
        "position": "bottom under main photo and across lower middle",
        "count": 5,
        "items": [
          "close-up portrait thumbnail with blurred face, beige cap and sunglasses",
          "close-up of sailor collar cardigan and oversized pink bow",
          "close-up of pastel pink plaid skirt fabric",
          "close-up of white socks and chunky cream loafers",
          "cafe detail thumbnail with flower vase and chalkboard menu"
        ]
      }
    },
    "right side": {
      "sections count": 4,
      "sections": [
        {
          "number": "01",
          "title": "CHARACTER OVERVIEW",
          "position": "top right",
          "text": "A soft and sweet café-inspired look that blends pastel tones with classic silhouettes. Gentle, approachable, and effortlessly polished."
        },
        {
          "number": "02",
          "title": "OUTFIT BREAKDOWN",
          "position": "upper right middle",
          "bullet count": 5,
          "bullets": [
            "Cardigan: Cream knit with petite pink ribbon details for a feminine touch.",
