        {
          "number": "03",
          "title": "COLOR PALETTE",
          "position": "right middle",
          "swatch count": 7,
          "swatches": [
            "Cream",
            "Blush Pink",
            "Dusty Rose",
            "Warm Beige",
            "Soft Taupe",
            "Café Brown",
            "Sage Green"
          ]
        },
        {
          "number": "04",
          "title": "ACCESSORIES & DETAILS",
          "position": "lower right",
          "detail count": 5,
          "details": [
            "Beige cap with sunglasses for a casual, sunny-day vibe.",
            "Pink shoulder bag adds color cohesion and practicality.",
            "Delicate earrings for a subtle and refined finish.",
            "Ribbon accents on cardigan and socks for sweet detailing.",
            "Iced drink adds to the relaxed café atmosphere."
          ],
          "inset image": "small vertical close-up photo of the pink shoulder bag and plaid skirt"
        }
      ]
    },
    "bottom analysis row": {
      "panel count": 4,
      "panels": [
        {
          "title": "FACIAL EXPRESSION",
          "icon": "simple smiley face line icon",
          "text": "Calm, sweet, and composed. Soft eye contact with a natural, approachable expression."
        },
        {
          "title": "HAIR & GROOMING",
          "icon": "simple hair/person line icon",
          "text": "Low side bun with soft flyaway strands. Natural makeup, smooth skin, and a clean finish."
        },
        {
          "title": "POSE & BODY LANGUAGE",
          "icon": "simple seated pose line icon",
          "text": "Seated at an outdoor café chair, legs crossed, holding drink with both hands—relaxed and poised."
        },
        {
          "title": "STYLE TAGS",
          "icon": "tag line icon",
          "tag count": 8,
          "tags": [
            "#CafeLook",
            "#SoftGirl",
            "#PastelPalette",
            "#SweetCasual",
            "#SpringStyle",
            "#CleanFashion",
            "#GirlyVibes",
            "#KoreanStyle"
          ]
        }
      ]
    }
  },
  "design details": "use thin dusty-pink horizontal rules between sections, small decorative sparkle and bow icon near the top right, rounded photo corners, generous margins, readable sans-serif typography, editorial spacing, realistic photo-collage imagery integrated with infographic text",
  "rendering": "high-resolution realistic lifestyle photography combined with clean vector UI elements, soft sunlight, shallow depth of field, pastel color grading, polished social-media template suitable for a character profile card"
}

